INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT121-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Since 1989, elephant ivory can't be imported into the U.S. or Canada, but mammoth ivory can. Right after the ban, imports labeled "mammoth" jumped. Customs couldn't tell the two apart. Once a technique to tell them apart became known, "mammoth" imports dropped sharply.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer. The "mammoth" imports rose when lying was undetectable and fell the moment it became detectable. The natural explanation: much of that "mammoth" ivory was elephant ivory with a false label.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Much of the "mammoth" ivory imported after the ban was really elephant ivory.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT121-S4-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
